() => {
  // Find any text mentioning colors or color options
  const text = document.body.innerText;
  const lines = text.split('\n').filter(l => l.toLowerCase().includes('color') || l.toLowerCase().includes('sky blue') || l.toLowerCase().includes('midnight') || l.toLowerCase().includes('starlight') || l.toLowerCase().includes('silver'));
  return lines.slice(0, 30).join('\n---\n');
}

() => {
  // Get all text content of the page, but structured
  const allText = document.body.innerText;
  // Look for color-related sections
  const colorSection = allText.indexOf('color');
  const result = {};
  result.textLength = allText.length;
  result.first2000 = allText.substring(0, 2000);
  if (colorSection > -1) {
    result.colorContext = allText.substring(colorSection, colorSection + 500);
  }
  return result;
}

() => {
  // Close any modals/overlays
  const closeButtons = document.querySelectorAll('button[aria-label*="Close"], .modal-close, [class*="close"]');
  closeButtons.forEach(b => b.click());
  // Also try to find if there's a specific overlay
  const overlay = document.querySelector('[class*="overlay"], [class*="modal"]');
  if (overlay) overlay.remove();
  return { closedButtons: closeButtons.length, hasOverlay: !!overlay };
}

() => {
  const overlay = document.querySelector('[class*="overlay"], [role="dialog"], .modal, [class*="modal"]');
  if (!overlay) return 'No overlay found';
  // Try to find close button
  const closeBtn = overlay.querySelector('button[aria-label*="lose"], button[class*="lose"], button[class*="dismiss"]');
  return { 
    overlayHTML: overlay.outerHTML.substring(0, 500),
    closeBtnFound: !!closeBtn,
    closeBtnText: closeBtn ? closeBtn.outerHTML.substring(0, 200) : null
  };
}

() => {
  // Force remove any potential overlays
  document.querySelectorAll('*').forEach(el => {
    const style = window.getComputedStyle(el);
    if ((style.position === 'fixed' || style.position === 'absolute') && 
        parseInt(style.zIndex) > 100 && 
        el.offsetWidth > 100 && 
        el.offsetHeight > 100) {
      // Skip if it might be the header or a video
      if (!el.closest('header') && el.tagName !== 'VIDEO' && el.tagName !== 'IMG') {
        el.remove();
      }
    }
  });
  return 'Overlay removed';
}

() => {
  // Find color swatches / color options
  const colorSection = document.querySelectorAll('[name*="color" i], [class*="color" i], [data-color]');
  // Try to find input radios near "Color" text
  const allInputs = document.querySelectorAll('input[type="radio"]');
  const results = [];
  allInputs.forEach(input => {
    if (input.name && input.name.toLowerCase().includes('color')) {
      const label = document.querySelector(`label[for="${input.id}"]`);
      results.push({
        id: input.id,
        name: input.name,
        value: input.value,
        ariaLabel: input.getAttribute('aria-label'),
        labelText: label ? label.innerText : null,
        labelHTML: label ? label.innerHTML.substring(0, 500) : null
      });
    }
  });
  return results;
}

() => {
  // Look at the color section more directly
  const allText = document.body.innerText;
  // Find the color section
  const idx = allText.indexOf('Color');
  if (idx > -1) {
    return allText.substring(idx, idx + 1000);
  }
  return 'Color section not found in text';
}
